INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist IPv6 immer schneller als IPv4?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt vom Netzwerk ab"}, {"text": "Ja", "correct": false, "because": "Nur mehr Adressen, nicht schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wähle ich für ein kleines lokales Netzwerk?', 3, '[{"text": "IPv4", "correct": true, "because": "Einfacher und ausreichend"}, {"text": "IPv6", "correct": false, "because": "Überdimensioniert für klein"}, {"text": "Keines", "correct": false, "because": "Adressierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Subnetze für Sicherheit nützlich?', 5, '[{"text": "Trennung von Geräten", "correct": true, "because": "Begrenzt Zugriff"}, {"text": "Kleinere Broadcast-Domänen", "correct": true, "because": "Weniger Kollisionen"}, {"text": "Höhere Geschwindigkeit", "correct": false, "because": "Nicht direkt"}, {"text": "Einfache Adressen", "correct": false, "because": "Komplexität steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv4 hat 32 Bit. b) IPv6 ist abwärtskompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, keine direkte Kompatibilität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung von Subnetzen?', 4, '[{"text": "Adressbereich", "correct": false, "because": "Kern der Subnetzung"}, {"text": "Maske", "correct": false, "because": "Definiert Grenzen"}, {"text": "Farbcodierung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob IPv4-Adressen bald aufgebraucht sind?', 2, '[{"text": "Ja", "correct": true, "because": "Begrenzte Anzahl fast erschöpft"}, {"text": "Nein", "correct": false, "because": "Schon knapp"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für ein großes Netzwerk?', 3, '[{"text": "IPv6", "correct": true, "because": "Mehr Adressen verfügbar"}, {"text": "IPv4", "correct": false, "because": "Adressen begrenzt"}, {"text": "Statische Adressen", "correct": false, "because": "Weniger flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet IPv6 gegenüber IPv4?', 5, '[{"text": "Größerer Adressraum", "correct": true, "because": "128 Bit vs. 32 Bit"}, {"text": "Einfachere Konfiguration", "correct": true, "because": "Autokonfiguration möglich"}, {"text": "Geringere Latenz", "correct": false, "because": "Nicht garantiert"}, {"text": "Billigere Nutzung", "correct": false, "because": "Kosten unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Subnetze erhöhen die Sicherheit. b) IPv6 braucht keine Subnetze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Subnetze auch bei IPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein privates Netzwerk?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzwerkgrenzen"}, {"text": "IP-Adressen", "correct": false, "because": "Grundlage der Kommunikation"}, {"text": "Globale IPv6-Adressen", "Correct": true, "because": "Private reichen aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat IPv6 weniger Overhead als IPv4?', 2, '[{"text": "Nein", "correct": true, "because": "Größere Header"}, {"text": "Ja", "correct": false, "because": "Nicht kleiner"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für Subnetzplanung entscheidend?', 4, '[{"text": "Anzahl Geräte", "correct": true, "because": "Bestimmt Adressbedarf"}, {"text": "Netzwerktrennung", "correct": true, "because": "Sicherheit und Struktur"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IPv4 mit NAT noch lange reicht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "NAT erweitert Nutzung"}, {"text": "Nein", "correct": false, "because": "Langfristig limitiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für ein Firmennetzwerk?', 3, '[{"text": "Subnetzstruktur", "correct": true, "because": "Sicherheit und Organisation"}, {"text": "Maximale Adressen", "correct": false, "because": "Sekundär"}, {"text": "Einfache Adressen", "correct": false, "because": "Komplexität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv6 hat 128 Bit. b) Subnetze sind bei IPv4 unnötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Subnetze wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat IPv4?', 5, '[{"text": "Begrenzter Adressraum", "correct": true, "because": "Nur 32 Bit"}, {"text": "NAT-Komplexität", "correct": true, "because": "Erschwert direkte Verbindungen"}, {"text": "Langsamere Verarbeitung", "correct": false, "because": "Nicht zwingend"}, {"text": "Schwierige Updates", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Adressierung für einen Server unwichtig?', 3, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzwerk"}, {"text": "IP-Version", "correct": false, "because": "Muss unterstützt werden"}, {"text": "Schöne Adressfolge", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht IPv6 die Sicherheit?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Adressraum, keine Sicherheitsgarantie"}, {"text": "Ja", "correct": false, "because": "Sicherheit nicht inhärent"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Subnetze die Latenz senken?', 2, '[{"text": "Nein", "correct": true, "because": "Latenz hardwareabhängig"}, {"text": "Ja", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressierung wähle ich für ein wachsendes Unternehmen?', 4, '[{"text": "IPv6 mit Subnetzen", "correct": true, "because": "Skalierbar und strukturiert"}, {"text": "IPv4 ohne Subnetze", "correct": false, "because": "Begrenzt und unstrukturiert"}, {"text": "Statische IPv4", "correct": false, "because": "Weniger flexibel"}]');
